namespace QuantForge.Core;public sealed record AndroidStrategyDraftCard(string DraftFingerprint,string StrategyId,int ParameterCount,bool ReadyForResearch,IReadOnlyList<string> Diagnostics,bool CanSubmitOrders);public static class AndroidStrategyDraftCardRules{public static AndroidStrategyDraftCard Create(StrategyDraft draft,StrategyDraftReview review){StrategyDraftRules.Validate(draft);if(review.DraftFingerprint!=draft.DraftFingerprint)throw new InvalidOperationException("Android strategy draft card review does not match the draft.");return new(draft.DraftFingerprint,draft.StrategyId,draft.Parameters.Count,review.ReadyForResearch,review.Diagnostics.ToArray(),false);}}
